@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="warehouse-label" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect" class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
        {
            <option value="@id">@name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

.warehouse-selector {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.warehouse-label {
    white-space: nowrap;
    font-weight: 500;
    font-size: 0.85rem;
}

.warehouse-selector .form-select {
    width: auto;
    min-width: 160px;
}

