arguments.file_text:
@page "/dashboard"
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>
<p class="text-muted">Monitoring <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="row mt-4">
    <div class="col-md-4">
        <div class="card @(alertCount > 5 ? "border-danger" : "border-warning")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(alertCount > 5 ? "text-danger" : "text-warning")">
                    @alertCount
                </p>
                <p class="card-text text-muted">
                    Items below minimum level
                </p>
            </div>
        </div>
    </div>

    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Polling Status</h5>
                <ul class="list-unstyled mb-0">
                    <li><strong>Warehouse:</strong> @WarehouseState.CurrentWarehouseId</li>
                    <li><strong>Last refresh:</strong> @lastRefresh.ToString("HH:mm:ss")</li>
                    <li><strong>Polling interval:</strong> 10 seconds</li>
                    <li><strong>Status:</strong> <span class="text-success">● Active</span></li>
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private int alertCount;
    private DateTime lastRefresh;
    private CancellationTokenSource? _cts;

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;

        await FetchAndBroadcastAsync();
        StartPolling();
    }

    private void StartPolling()
    {
        _cts = new CancellationTokenSource();
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await timer.WaitForNextTickAsync(ct))
            {
                await FetchAndBroadcastAsync();
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / warehouse switch.
        }
    }

    private async Task FetchAndBroadcastAsync()
    {
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        lastRefresh = DateTime.Now;
    }

    private void OnAlertDataChanged()
    {
        alertCount = AlertService.LastKnownCount;
        InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        // Restart polling for the newly selected warehouse.
        _cts?.Cancel();
        await FetchAndBroadcastAsync();
        StartPolling();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
    }
}

